// IP
fn highlight_ip(text: &str) -> String {
    static RE: Lazy<Regex> = Lazy::new(|| Regex::new(r"\b(?:(?:25[0-5]|2[0-4]\d|[01]?\d?\d)\.){3}(?:25[0-5]|2[0-4]\d|[01]?\d?\d)\b").unwrap());
    RE.replace_all(text, |caps: &regex::Captures| {
        let ip = caps.get(0).unwrap().as_str();
        // color each octet italic blue, dot red
        let parts: Vec<&str> = ip.split('.').collect();
        let mut out = String::new();
        for (i, part) in parts.iter().enumerate() {
            out.push_str(&format!("\x1b[3;34m{}\x1b[0m", part));
            if i < 3 {
                out.push_str("\x1b[31m.\x1b[0m");
            }
        }
        out
    }).to_string()
}

// UUID
fn highlight_uuid(text: &str) -> String {
    static RE: Lazy<Regex> = Lazy::new(|| Regex::new(r"\b[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\b").unwrap());
    RE.replace_all(text, |caps: &regex::Captures| {
        let uuid = caps.get(0).unwrap().as_str();
        let mut out = String::new();
        for ch in uuid.chars() {
            if ch == '-' {
                out.push_str("\x1b[31m-\x1b[0m");
            } else if ch.is_ascii_digit() {
                out.push_str(&format!("\x1b[3;34m{}\x1b[0m", ch));
            } else {
                // hex letter
                out.push_str(&format!("\x1b[3;35m{}\x1b[0m", ch));
            }
        }
        out
    }).to_string()
}

// Pointer: 0x + 8 hex
