    RE.replace_all(text, |caps: &regex::Captures| {
        let m = caps.get(0).unwrap();
        let start = m.start();
        let end = m.end();
        let prev = if start>0 { text[..start].chars().last() } else { None };
        let next = text[end..].chars().next();
        let is_word = |c: Option<char>| c.map(|ch| ch.is_alphanumeric() || ch=='_').unwrap_or(false);
        if is_word(prev) || is_word(next) {
            m.as_str().to_string()
        } else {
            format!("\x1b[36m{}\x1b[0m", m.as_str())
        }
    }).to_string()
}

