fn highlight_paths(text: &str) -> String {
    static RE_CAND: Lazy<Regex> = Lazy::new(|| Regex::new(r"(?P<p>(?:\./|\.\./|/)?(?:[\w\-.]+/)+[\w\-.]+/?|/[\w\-.]+/[\w\-.]+(?:/[\w\-.]+)*/?)").unwrap());
    RE_CAND.replace_all(text, |caps: &regex::Captures| {
        let path_str = caps.name("p").unwrap().as_str();
        let slash_count = path_str.matches('/').count();
        if slash_count < 2 {
            return path_str.to_string();
        }
        if path_str == "/" {
            return path_str.to_string();
        }
        let mut out = String::new();
        let chars: Vec<char> = path_str.chars().collect();
        let mut i = 0;
        while i < chars.len() {
            if chars[i] == '/' {
                out.push_str("\x1b[33m/\x1b[0m");
                i+=1;
            } else {
                let mut seg = String::new();
                while i < chars.len() && chars[i] != '/' {
                    seg.push(chars[i]);
                    i+=1;
                }
                if !seg.is_empty() {
                    out.push_str(&format!("\x1b[32m{}\x1b[0m", seg));
                }
            }
        }
        out
    }).to_string()
}

