fn highlight_urls(text: &str) -> String {
    static RE: Lazy<Regex> = Lazy::new(|| Regex::new(r"https?://[^\s]+").unwrap());
    RE.replace_all(text, |caps: &regex::Captures| {
        let url = caps.get(0).unwrap().as_str();
        let scheme_end = url.find("://").unwrap();
        let scheme = &url[..scheme_end];
        let rest = &url[scheme_end+3..];
        let mut out = String::new();
        if scheme == "https" {
            out.push_str(&format!("\x1b[2;32m{}\x1b[0m", scheme));
        } else if scheme == "http" {
            out.push_str(&format!("\x1b[2;31m{}\x1b[0m", scheme));
        } else {
            out.push_str(scheme);
        }
        out.push_str("://");
        let mut host_end = rest.len();
        for (i,c) in rest.char_indices() {
            if c=='/' || c=='?' || c=='#' {
                host_end = i;
                break;
            }
            if c==':' {
                host_end = i;
                break;
            }
        }
        let host = &rest[..host_end];
        let after_host = &rest[host_end..];
        let ip_re = Regex::new(r"^(?:(?:25[0-5]|2[0-4]\d|[01]?\d?\d)\.){3}(?:25[0-5]|2[0-4]\d|[01]?\d?\d)$").unwrap();
        if ip_re.is_match(host) {
            let parts: Vec<&str> = host.split('.').collect();
            for (i,p) in parts.iter().enumerate() {
                out.push_str(&format!("\x1b[3;34m{}\x1b[0m", p));
                if i<3 { out.push_str("\x1b[31m.\x1b[0m"); }
            }
        } else {
            if !host.is_empty() {
                out.push_str(&format!("\x1b[2;34m{}\x1b[0m", host));
            }
        }
        let mut remaining = after_host;
        if remaining.starts_with(':') {
            let mut port_end = 1;
            while port_end < remaining.len() && remaining[port_end..].chars().next().map(|ch| ch.is_ascii_digit()).unwrap_or(false) {
                port_end+=1;
            }
            let port_str = &remaining[..port_end];
            out.push_str(port_str);
            remaining = &remaining[port_end..];
        }
        if remaining.starts_with('/') {
            let mut path_end = remaining.len();
            for (i,c) in remaining.char_indices() {
                if c=='?' || c=='#' {
                    path_end = i;
                    break;
                }
            }
            let path_str = &remaining[..path_end];
            if !path_str.is_empty() {
                out.push_str(&format!("\x1b[34m{}\x1b[0m", path_str));
            }
            remaining = &remaining[path_end..];
        }
        if remaining.starts_with('?') {
            out.push_str("\x1b[31m?\x1b[0m");
            remaining = &remaining[1..];
            let frag_pos = remaining.find('#');
            let query_part = if let Some(pos) = frag_pos { &remaining[..pos] } else { remaining };
            let frag_part = if let Some(pos) = frag_pos { &remaining[pos..] } else { "" };
            let mut first = true;
            for pair in query_part.split('&') {
                if !first {
                    out.push_str("\x1b[31m&\x1b[0m");
                }
                first = false;
                if let Some(eq_pos) = pair.find('=') {
                    let k = &pair[..eq_pos];
                    let v = &pair[eq_pos+1..];
                    out.push_str(&format!("\x1b[35m{}\x1b[0m", k));
                    out.push_str("\x1b[31m=\x1b[0m");
                    out.push_str(&format!("\x1b[36m{}\x1b[0m", v));
                } else {
                    out.push_str(&format!("\x1b[35m{}\x1b[0m", pair));
                }
            }
            if !frag_part.is_empty() {
                out.push_str(frag_part);
            }
        } else if remaining.starts_with('#') {
            out.push_str(remaining);
        }
        out
    }).to_string()
}

fn highlight_builtin(text: &str, disable: bool) -> String {
    if disable {
        return text.to_string();
    }
    let mut res = text.to_string();
    static RE_BOOL: Lazy<Regex> = Lazy::new(|| Regex::new(r"\b(?:true|false|null)\b").unwrap());
    res = RE_BOOL.replace_all(&res, |caps: &regex::Captures| {
        let s = caps.get(0).unwrap().as_str();
        format!("\x1b[3;31m{}\x1b[0m", s)
    }).to_string();
    static RE_INFO: Lazy<Regex> = Lazy::new(|| Regex::new(r"\bINFO\b").unwrap());
    static RE_WARN: Lazy<Regex> = Lazy::new(|| Regex::new(r"\bWARN\b").unwrap());
    static RE_ERROR: Lazy<Regex> = Lazy::new(|| Regex::new(r"\bERROR\b").unwrap());
    static RE_DEBUG: Lazy<Regex> = Lazy::new(|| Regex::new(r"\bDEBUG\b").unwrap());
    static RE_TRACE: Lazy<Regex> = Lazy::new(|| Regex::new(r"\bTRACE\b").unwrap());
    res = RE_INFO.replace_all(&res, "\x1b[37mINFO\x1b[0m").to_string();
    res = RE_WARN.replace_all(&res, "\x1b[33mWARN\x1b[0m").to_string();
    res = RE_ERROR.replace_all(&res, "\x1b[31mERROR\x1b[0m").to_string();
    res = RE_DEBUG.replace_all(&res, "\x1b[32mDEBUG\x1b[0m").to_string();
    res = RE_TRACE.replace_all(&res, "\x1b[2mTRACE\x1b[0m").to_string();
    static RE_GET: Lazy<Regex> = Lazy::new(|| Regex::new(r"\bGET\b").unwrap());
    static RE_POST: Lazy<Regex> = Lazy::new(|| Regex::new(r"\bPOST\b").unwrap());
    static RE_PUT: Lazy<Regex> = Lazy::new(|| Regex::new(r"\bPUT\b").unwrap());
    static RE_DELETE: Lazy<Regex> = Lazy::new(|| Regex::new(r"\bDELETE\b").unwrap());
    static RE_PATCH: Lazy<Regex> = Lazy::new(|| Regex::new(r"\bPATCH\b").unwrap());
    res = RE_GET.replace_all(&res, "\x1b[42;30m GET \x1b[0m").to_string();
    res = RE_POST.replace_all(&res, "\x1b[43;30m POST \x1b[0m").to_string();
    res = RE_PUT.replace_all(&res, "\x1b[45;30m PUT \x1b[0m").to_string();
    res = RE_DELETE.replace_all(&res, "\x1b[41;30m DELETE \x1b[0m").to_string();
    res = RE_PATCH.replace_all(&res, "\x1b[45;30m PATCH \x1b[0m").to_string();
    res
}

fn highlight_custom(text: &str, custom_keywords: &[CustomKeyword], cli_highlights: &[(String, Vec<String>)]) -> String {
    let mut res = text.to_string();
    for kw in custom_keywords {
        for word in &kw.words {
            let pattern = format!(r"\b{}\b", regex::escape(word));
            let re = Regex::new(&pattern).unwrap();
            let style = kw.style.clone();
            res = re.replace_all(&res, |_caps: &regex::Captures| {
                apply_style(word, &style)
            }).to_string();
        }
    }
    for (color, words) in cli_highlights {
        let style = style_from_cli_color(color);
        for word in words {
            if word.is_empty() { continue; }
            let pattern = format!(r"\b{}\b", regex::escape(word));
            let re = Regex::new(&pattern).unwrap();
            res = re.replace_all(&res, |_caps: &regex::Captures| {
                apply_style(word, &style)
            }).to_string();
        }
    }
    res
}

fn highlight_line_correct(line: &str, enabled: &HashSet<String>, disable_builtin: bool, custom_keywords: &[CustomKeyword], cli_highlights: &[(String, Vec<String>)]) -> String {
    let mut res = line.to_string();
    if enabled.contains("numbers") {
        res = highlight_numbers(&res);
    }
    if enabled.contains("quotes") {
        res = highlight_quotes(&res);
    }
    if enabled.contains("json") {
        res = highlight_json(&res);
    }
    if enabled.contains("key-value-pairs") {
        res = highlight_key_value(&res);
    }
    if enabled.contains("paths") {
        res = highlight_paths(&res);
    }
    if enabled.contains("processes") {
        res = highlight_processes(&res);
    }
    if enabled.contains("dates") {
        res = highlight_dates(&res);
    }
    if enabled.contains("urls") {
        res = highlight_urls(&res);
    }
    if enabled.contains("pointers") {
        res = highlight_pointer(&res);
    }
    if enabled.contains("uuids") {
        res = highlight_uuid(&res);
    }
    if enabled.contains("ip-addresses") {
        res = highlight_ip(&res);
    }
    res = highlight_builtin(&res, disable_builtin);
    res = highlight_custom(&res, custom_keywords, cli_highlights);
    res
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let help_short = r#"A log file highlighter

Usage: executable [OPTIONS] [FILE]

Arguments:
  [FILE]  Filepath

Options:
  -f, --follow
          Follow the contents of a file
  -p, --print
          Print the output to stdout
      --config-path <CONFIG_PATH>
          Provide a custom path to a configuration file
  -e, --exec <EXEC>
          Run command and view the output in a pager
      --highlight <COLOR_WORD>
          Highlights in the form color:word1,word2
      --enable <ENABLED_HIGHLIGHTERS>
          Enable specific highlighters [possible values: numbers, urls, pointers, dates, paths,
          quotes, key-value-pairs, uuids, ip-addresses, processes, json]
      --disable <DISABLED_HIGHLIGHTERS>
          Disable specific highlighters [possible values: numbers, urls, pointers, dates, paths,
          quotes, key-value-pairs, uuids, ip-addresses, processes, json]
      --disable-builtin-keywords
          Disable the highlighting of all builtin keyword groups (booleans, nulls, log severities
          and common REST verbs)
      --pager <PAGER>
          Override the default pager command used by tspin. (e.g. `--pager="ov -f [FILE]"`) [env:
          TAILSPIN_PAGER=]
  -h, --help
          Print help (see more with '--help')
  -V, --version
          Print version
"#;
    let help_long = r#"A log file highlighter

Usage: executable [OPTIONS] [FILE]

Arguments:
  [FILE]
          Filepath

Options:
  -f, --follow
          Follow the contents of a file

  -p, --print
          Print the output to stdout

      --config-path <CONFIG_PATH>
          Provide a custom path to a configuration file

  -e, --exec <EXEC>
          Run command and view the output in a pager

      --highlight <COLOR_WORD>
          Highlights in the form color:word1,word2

          [possible values: red, green, yellow, blue, magenta, cyan]

      --enable <ENABLED_HIGHLIGHTERS>
          Enable specific highlighters

          [possible values: numbers, urls, pointers, dates, paths, quotes, key-value-pairs, uuids,
          ip-addresses, processes, json]

      --disable <DISABLED_HIGHLIGHTERS>
          Disable specific highlighters

          [possible values: numbers, urls, pointers, dates, paths, quotes, key-value-pairs, uuids,
          ip-addresses, processes, json]

      --disable-builtin-keywords
          Disable the highlighting of all builtin keyword groups (booleans, nulls, log severities
          and common REST verbs)

      --pager <PAGER>
          Override the default pager command used by tspin. (e.g. `--pager="ov -f [FILE]"`)

          [env: TAILSPIN_PAGER=]

  -h, --help
          Print help (see a summary with '-h')

  -V, --version
          Print version
"#;

    if args.iter().any(|a| a=="-h") {
        print!("{}", help_short);
        std::process::exit(0);
    }
    if args.iter().any(|a| a=="--help") {
        print!("{}", help_long);
        std::process::exit(0);
    }
    if args.iter().any(|a| a=="-V" || a=="--version") {
        println!("tspin {}", VERSION);
        std::process::exit(0);
    }

    let mut clap_cmd = ClapCommand::new("tspin")
        .version(VERSION)
        .about("A log file highlighter")
        .arg(Arg::new("FILE").value_name("FILE").help("Filepath"))
        .arg(Arg::new("follow").short('f').long("follow").action(ArgAction::SetTrue).help("Follow the contents of a file"))
        .arg(Arg::new("print").short('p').long("print").action(ArgAction::SetTrue).help("Print the output to stdout"))
        .arg(Arg::new("config-path").long("config-path").value_name("CONFIG_PATH").help("Provide a custom path to a configuration file"))
        .arg(Arg::new("exec").short('e').long("exec").value_name("EXEC").help("Run command and view the output in a pager"))
        .arg(Arg::new("highlight").long("highlight").value_name("COLOR_WORD").help("Highlights in the form color:word1,word2").action(ArgAction::Append))
        .arg(Arg::new("enable").long("enable").value_name("ENABLED_HIGHLIGHTERS").help("Enable specific highlighters").value_parser(["numbers","urls","pointers","dates","paths","quotes","key-value-pairs","uuids","ip-addresses","processes","json"]).action(ArgAction::Append).value_delimiter(','))
        .arg(Arg::new("disable").long("disable").value_name("DISABLED_HIGHLIGHTERS").help("Disable specific highlighters").value_parser(["numbers","urls","pointers","dates","paths","quotes","key-value-pairs","uuids","ip-addresses","processes","json"]).action(ArgAction::Append).value_delimiter(','))
        .arg(Arg::new("disable-builtin-keywords").long("disable-builtin-keywords").action(ArgAction::SetTrue).help("Disable the highlighting of all builtin keyword groups (booleans, nulls, log severities and common REST verbs)"))
        .arg(Arg::new("pager").long("pager").value_name("PAGER").help("Override the default pager command used by tspin. (e.g. `--pager=\"ov -f [FILE]\"`)").env("TAILSPIN_PAGER"));

    let matches = match clap_cmd.try_get_matches_from(args.clone()) {
        Ok(m) => m,
        Err(e) => {
            e.print().unwrap();
            std::process::exit(2);
        }
    };

    let file_opt = matches.get_one::<String>("FILE").map(|s| s.to_string());
    let follow = matches.get_flag("follow");
    let print_flag = matches.get_flag("print");
    let config_path_opt = matches.get_one::<String>("config-path").map(|s| s.to_string());
    let exec_opt = matches.get_one::<String>("exec").map(|s| s.to_string());
    let disable_builtin = matches.get_flag("disable-builtin-keywords");
    let pager_opt = matches.get_one::<String>("pager").map(|s| s.to_string());

    let highlight_vals: Vec<String> = matches.get_many::<String>("highlight").map(|vals| vals.cloned().collect()).unwrap_or_default();
    let mut cli_highlights: Vec<(String, Vec<String>)> = Vec::new();
    for hv in highlight_vals {
        if !hv.contains(':') {
            eprintln!("error: invalid value '{}' for '--highlight <COLOR_WORD>': Expected format COLOR:word1,word2,... found `{}`", hv, hv);
            eprintln!("\nFor more information, try '--help'.");
            std::process::exit(2);
        }
        let parts: Vec<&str> = hv.splitn(2, ':').collect();
        let color = parts[0].to_string();
        let words_part = parts[1];
        let valid_colors = ["red","green","yellow","blue","magenta","cyan"];
        if !valid_colors.contains(&color.as_str()) {
            eprintln!("error: invalid value '{}' for '--highlight <COLOR_WORD>': invalid variant: {}", hv, color);
            eprintln!("\nFor more information, try '--help'.");
            std::process::exit(2);
        }
        let words: Vec<String> = if words_part.is_empty() {
            vec![]
        } else {
            words_part.split(',').map(|s| s.to_string()).filter(|s| !s.is_empty()).collect()
        };
        cli_highlights.push((color, words));
    }

    let enable_vals: Vec<String> = matches.get_many::<String>("enable").map(|vals| vals.cloned().collect()).unwrap_or_default();
    let disable_vals: Vec<String> = matches.get_many::<String>("disable").map(|vals| vals.cloned().collect()).unwrap_or_default();

    if !enable_vals.is_empty() && !disable_vals.is_empty() {
        eprintln!("Error:   × cannot both enable and disable highlighters\n");
        std::process::exit(1);
    }

    let all_groups = vec!["numbers","urls","pointers","dates","paths","quotes","key-value-pairs","uuids","ip-addresses","processes","json"];
    let mut enabled_set: HashSet<String> = HashSet::new();
    if !enable_vals.is_empty() {
        for v in enable_vals {
            enabled_set.insert(v);
        }
    } else if !disable_vals.is_empty() {
        for g in &all_groups {
            if !disable_vals.contains(&g.to_string()) {
                enabled_set.insert(g.to_string());
            }
        }
    } else {
        for g in &all_groups {
            enabled_set.insert(g.to_string());
        }
    }

    let mut custom_keywords: Vec<CustomKeyword> = Vec::new();
    if let Some(cfg_path) = config_path_opt {
        match parse_config(&cfg_path) {
            Ok(kw) => custom_keywords = kw,
            Err(e) => {
                if e == "could not find the TOML file" {
                    eprintln!("Error:   × could not find the TOML file\n");
                    std::process::exit(1);
                } else {
                    // try to get detailed toml error from file content
                    let content = std::fs::read_to_string(&cfg_path).unwrap_or_default();
                    match content.parse::<toml::Value>() {
                        Ok(_) => {
                            eprintln!("Error:   × TOML parse error at line 1, column 1\n  │   |\n  │ 1 | ...\n  │   | ^...\n  │ {} \n", e);
                        },
                        Err(parse_err) => {
                            eprintln!("Error:   × {}\n", parse_err);
                        }
                    }
                    std::process::exit(1);
                }
            }
        }
    } else {
        let mut default_path: Option<String> = None;
        if let Ok(xdg) = std::env::var("XDG_CONFIG_HOME") {
            default_path = Some(format!("{}/tailspin/theme.toml", xdg));
        } else if let Ok(home) = std::env::var("HOME") {
            default_path = Some(format!("{}/.config/tailspin/theme.toml", home));
        }
        if let Some(p) = default_path {
            if std::path::Path::new(&p).exists() {
                if let Ok(kw) = parse_config(&p) {
                    custom_keywords = kw;
                }
            }
        }
    }

    let is_stdin_tty = io::stdin().is_terminal();
    let is_stdout_tty = io::stdout().is_terminal();

    let stdin_pipe = !is_stdin_tty;

    let use_pager = if print_flag {
        false
    } else {
        if stdin_pipe {
            false
        } else {
            if file_opt.is_some() || exec_opt.is_some() {
                true
            } else {
                false
            }
        }
    };

    let highlight_content = |content: String| -> String {
        let mut out_lines = Vec::new();
        for line in content.lines() {
            let highlighted = highlight_line_correct(line, &enabled_set, disable_builtin, &custom_keywords, &cli_highlights);
            out_lines.push(highlighted);
        }
        out_lines.join("\n")
    };

    if let Some(exec_cmd) = exec_opt {
        let output = Command::new("sh").arg("-c").arg(&exec_cmd).output();
        let highlighted = if let Ok(out) = output {
            let stdout = String::from_utf8_lossy(&out.stdout).to_string();
            highlight_content(stdout)
        } else {
            String::new()
        };
        if !use_pager {
            println!("{}", highlighted);
        } else {
            let pager_cmd = pager_opt.or_else(|| std::env::var("TAILSPIN_PAGER").ok()).unwrap_or_else(|| "less -R".to_string());
            if !pager_cmd.contains("[FILE]") {
                eprintln!("Error:   × Could not parse custom pager command\n");
                std::process::exit(1);
            }
            let dir = tempfile::tempdir().unwrap();
            let file_path = dir.path().join("tailspin.temp");
            std::fs::write(&file_path, highlighted).unwrap();
            let pager_final = pager_cmd.replace("[FILE]", file_path.to_str().unwrap());
            let status = Command::new("sh").arg("-c").arg(&pager_final).status();
            if let Ok(st) = status {
                if !st.success() {
                    eprintln!("Error: less::non_zero_exit\n\n  × Pager exited with non-zero status: exit status: {}", st.code().unwrap_or(1));
                    std::process::exit(1);
                }
            }
        }
        return;
    }

    if let Some(file_path) = file_opt {
        let content = match std::fs::read_to_string(&file_path) {
            Ok(c) => c,
            Err(_) => {
                eprintln!("Error:   ⚠  \x1b[33m{}\x1b[0m: No such file or directory\n", file_path);
                std::process::exit(1);
            }
        };
        if follow {
            if !use_pager {
                let highlighted = highlight_content(content.clone());
                println!("{}", highlighted);
                use std::thread::sleep;
                use std::time::Duration;
                let mut last_len = content.len();
                loop {
                    sleep(Duration::from_millis(200));
                    if let Ok(new_content) = std::fs::read_to_string(&file_path) {
                        if new_content.len() > last_len {
                            let added = &new_content[last_len..];
                            let highlighted_added = highlight_content(added.to_string());
                            print!("{}", highlighted_added);
                            use std::io::Write;
                            std::io::stdout().flush().unwrap();
                            last_len = new_content.len();
                        }
                    }
                }
            } else {
                let highlighted = highlight_content(content);
                let pager_cmd = pager_opt.or_else(|| std::env::var("TAILSPIN_PAGER").ok()).unwrap_or_else(|| "less -R".to_string());
                if !pager_cmd.contains("[FILE]") {
                    eprintln!("Error:   × Could not parse custom pager command\n");
                    std::process::exit(1);
                }
                let dir = tempfile::tempdir().unwrap();
                let temp_path = dir.path().join("tailspin.temp");
                std::fs::write(&temp_path, highlighted).unwrap();
                let pager_final = pager_cmd.replace("[FILE]", temp_path.to_str().unwrap());
                let _ = Command::new("sh").arg("-c").arg(&pager_final).status();
            }
        } else {
            let highlighted = highlight_content(content);
            if !use_pager {
                println!("{}", highlighted);
            } else {
                let pager_cmd = pager_opt.or_else(|| std::env::var("TAILSPIN_PAGER").ok()).unwrap_or_else(|| "less -R".to_string());
                if !pager_cmd.contains("[FILE]") {
                    eprintln!("Error:   × Could not parse custom pager command\n");
                    std::process::exit(1);
                }
                let dir = tempfile::tempdir().unwrap();
                let temp_path = dir.path().join("tailspin.temp");
                std::fs::write(&temp_path, highlighted).unwrap();
                let pager_final = pager_cmd.replace("[FILE]", temp_path.to_str().unwrap());
                let status = Command::new("sh").arg("-c").arg(&pager_final).status();
                if let Ok(st) = status {
                    if !st.success() {
                        eprintln!("Error: less::non_zero_exit\n\n  × Pager exited with non-zero status: exit status: {}", st.code().unwrap_or(1));
                        std::process::exit(1);
                    }
                }
            }
        }
        return;
    }

    let mut stdin_content = String::new();
    {
        let stdin = io::stdin();
        let mut handle = stdin.lock();
        handle.read_to_string(&mut stdin_content).unwrap();
    }
    if stdin_content.is_empty() && is_stdin_tty {
        return;
    }
    let highlighted = highlight_content(stdin_content);
    println!("{}", highlighted);
}
