        "bright_white" => Some("97"),
        "default" => Some("39"),
        _ => None,
    }
}
fn bg_code(name: &str) -> Option<&'static str> {
    match name {
        "black" => Some("40"),
        "red" => Some("41"),
        "green" => Some("42"),
        "yellow" => Some("43"),
        "blue" => Some("44"),
