    if let Some(m) = RE.find(remaining) {
        if m.start()!=0 { return None; }
        let uuid = m.as_str();
        let end = pos + uuid.len();
        if pos>0 && is_word_char(line[..pos].chars().last().unwrap()) { return None; }
        if end < line.len() && is_word_char(line[end..].chars().next().unwrap()) { return None; }
        let mut out = String::new();
        for ch in uuid.chars() {
            if ch == '-' {
                out.push_str("\x1b[31m-\x1b[0m");
            } else if ch.is_ascii_digit() {
                out.push_str(&format!("\x1b[3;34m{}\x1b[0m", ch));
            } else {
                out.push_str(&format!("\x1b[3;35m{}\x1b[0m", ch));
