fn try_url(line: &str, pos: usize) -> Option<(String, usize)> {
    static RE: Lazy<Regex> = Lazy::new(|| Regex::new(r"^https?://[^\s]+").unwrap());
    let remaining = &line[pos..];
    if let Some(m) = RE.find(remaining) {
        if m.start()!=0 { return None; }
        let url = m.as_str();
        let scheme_end = url.find("://").unwrap();
        let scheme = &url[..scheme_end];
        let rest = &url[scheme_end+3..];
        let mut out = String::new();
        if scheme == "https" {
            out.push_str(&format!("\x1b[2;32m{}\x1b[0m", scheme));
        } else if scheme == "http" {
            out.push_str(&format!("\x1b[2;31m{}\x1b[0m", scheme));
        } else {
            out.push_str(scheme);
        }
        out.push_str("://");
        let mut host_end = rest.len();
        for (i,c) in rest.char_indices() {
            if c=='/' || c=='?' || c=='#' {
                host_end = i;
                break;
            }
            if c==':' {
                host_end = i;
                break;
            }
        }
        let host = &rest[..host_end];
        let after_host = &rest[host_end..];
        let ip_re = Regex::new(r"^(?:(?:25[0-5]|2[0-4]\d|[01]?\d?\d)\.){3}(?:25[0-5]|2[0-4]\d|[01]?\d?\d)$").unwrap();
        if ip_re.is_match(host) {
            let parts: Vec<&str> = host.split('.').collect();
            for (i,p) in parts.iter().enumerate() {
                out.push_str(&format!("\x1b[3;34m{}\x1b[0m", p));
                if i<3 { out.push_str("\x1b[31m.\x1b[0m"); }
            }
        } else {
            if !host.is_empty() {
                out.push_str(&format!("\x1b[2;34m{}\x1b[0m", host));
            }
        }
        let mut remaining = after_host;
        if remaining.starts_with(':') {
            let mut port_end = 1;
            while port_end < remaining.len() && remaining[port_end..].chars().next().map(|ch| ch.is_ascii_digit()).unwrap_or(false) {
                port_end+=1;
            }
            let port_str = &remaining[..port_end];
            out.push_str(port_str);
            remaining = &remaining[port_end..];
        }
        if remaining.starts_with('/') {
            let mut path_end = remaining.len();
            for (i,c) in remaining.char_indices() {
                if c=='?' || c=='#' {
                    path_end = i;
                    break;
                }
            }
            let path_str = &remaining[..path_end];
            if !path_str.is_empty() {
                // Check if path_str is empty blue? In original, url with only domain plus "/" gave "/" blue? For "https://example.com/" we saw "/" blue? Let's see output for "https://example.com/" was "://[domain][/\n]..." Actually we saw for "https://example.com/" output was "://[domain]^[[34m/^[[0m" so "/" blue.
                out.push_str(&format!("\x1b[34m{}\x1b[0m", path_str));
            }
            remaining = &remaining[path_end..];
        } else {
            // For URL like "https://example.com" without path, original produced an empty blue segment? We saw "^[[2;34mexample.com^[[0m^[[34m^[[0m" - that is domain faint blue, then empty blue. That empty blue might be due to our parsing thinking path empty but we add empty blue? Let's check original for "https://example.com" (no slash): it gave domain faint blue + empty blue. So we should add empty blue when no path? Actually our code currently would not add path, so no empty blue. We need to add empty blue for consistency? Let's check: For "https://example.com", we observed ^[[2;32mhttps^[[0m://^[[2;34mexample.com^[[0m^[[34m^[[0m - that's scheme, ://, domain faint blue, then empty blue segment (34m then 0m with no content). That empty blue is weird but we should replicate: after domain, always add empty blue? Or when path is missing, add empty blue placeholder?
            // Let's add empty blue when path is empty and no query/fragment? That would match "https://example.com" case.
            if remaining.is_empty() {
                out.push_str("\x1b[34m\x1b[0m");
            }
        }
        if remaining.starts_with('?') {
            out.push_str("\x1b[31m?\x1b[0m");
            remaining = &remaining[1..];
            let frag_pos = remaining.find('#');
            let query_part = if let Some(pos) = frag_pos { &remaining[..pos] } else { remaining };
            let frag_part = if let Some(pos) = frag_pos { &remaining[pos..] } else { "" };
            let mut first = true;
            for pair in query_part.split('&') {
                if !first {
                    out.push_str("\x1b[31m&\x1b[0m");
                }
                first = false;
                if let Some(eq_pos) = pair.find('=') {
                    let k = &pair[..eq_pos];
                    let v = &pair[eq_pos+1..];
                    out.push_str(&format!("\x1b[35m{}\x1b[0m", k));
                    out.push_str("\x1b[31m=\x1b[0m");
                    out.push_str(&format!("\x1b[36m{}\x1b[0m", v));
                } else {
                    out.push_str(&format!("\x1b[35m{}\x1b[0m", pair));
                }
            }
            if !frag_part.is_empty() {
                out.push_str(frag_part);
            }
        } else if remaining.starts_with('#') {
            out.push_str(remaining);
        }
        return Some((out, url.len()));
    }
    None
}

