fn highlight_dates_for_match(s: &str) -> String {
    // Color date parts magenta, time blue, separators
    // This is similar to highlight_dates but for a single matched token
    // We'll implement same as before but for just this token
    let mut result = s.to_string();
    // datetime with T or space
    let re_dt = Regex::new(r"(?P<y>\d{4})(?P<sep1>[-/])(?P<m>\d{2})(?P<sep2>[-/])(?P<d>\d{2})(?P<sep_dt>[T ])(?P<h>\d{2}):(?P<min>\d{2}):(?P<s>\d{2})(?:(?P<frac_sep>[.,])(?P<frac>\d+))?(?P<z>Z)?").unwrap();
    if let Some(caps) = re_dt.captures(s) {
        let y = &caps["y"];
        let sep1 = &caps["sep1"];
        let m = &caps["m"];
        let sep2 = &caps["sep2"];
        let d = &caps["d"];
        let sep_dt = &caps["sep_dt"];
        let h = &caps["h"];
        let min = &caps["min"];
        let sec = &caps["s"];
        let frac_sep = caps.name("frac_sep").map(|m| m.as_str());
        let frac = caps.name("frac").map(|m| m.as_str());
        let z = caps.name("z").map(|m| m.as_str());
        let mut out = String::new();
        out.push_str(&format!("\x1b[35m{}\x1b[0m", y));
        out.push_str(&format!("\x1b[2m{}\x1b[0m", sep1));
        out.push_str(&format!("\x1b[35m{}\x1b[0m", m));
        out.push_str(&format!("\x1b[2m{}\x1b[0m", sep2));
        out.push_str(&format!("\x1b[35m{}\x1b[0m", d));
        out.push_str(&format!("\x1b[31m{}\x1b[0m", sep_dt));
        out.push_str(&format!("\x1b[34m{}\x1b[0m", h));
        out.push_str("\x1b[2m:\x1b[0m");
        out.push_str(&format!("\x1b[34m{}\x1b[0m", min));
        out.push_str("\x1b[2m:\x1b[0m");
        out.push_str(&format!("\x1b[34m{}\x1b[0m", sec));
        if let (Some(fs), Some(f)) = (frac_sep, frac) {
            out.push_str(&format!("\x1b[2m{}\x1b[0m", fs));
            out.push_str(&format!("\x1b[34m{}\x1b[0m", f));
        }
        if let Some(z_str) = z {
            out.push_str(&format!("\x1b[31m{}\x1b[0m", z_str));
        }
        return out;
    }
    // date only
    let re_date = Regex::new(r"(?P<y>\d{4})(?P<sep1>[-/])(?P<m>\d{2})(?P<sep2>[-/])(?P<d>\d{2})").unwrap();
    if let Some(caps) = re_date.captures(s) {
        let y = &caps["y"];
        let sep1 = &caps["sep1"];
        let m = &caps["m"];
        let sep2 = &caps["sep2"];
        let d = &caps["d"];
        return format!("\x1b[35m{}\x1b[0m\x1b[2m{}\x1b[0m\x1b[35m{}\x1b[0m\x1b[2m{}\x1b[0m\x1b[35m{}\x1b[0m", y, sep1, m, sep2, d);
    }
    // time only
    let re_time = Regex::new(r"(?P<h>\d{2}):(?P<m>\d{2}):(?P<s>\d{2})(?:(?P<frac_sep>[.,])(?P<frac>\d+))?").unwrap();
    if let Some(caps) = re_time.captures(s) {
        let h = &caps["h"];
        let m = &caps["m"];
        let sec = &caps["s"];
        let mut out = format!("\x1b[34m{}\x1b[0m\x1b[2m:\x1b[0m\x1b[34m{}\x1b[0m\x1b[2m:\x1b[0m\x1b[34m{}\x1b[0m", h, m, sec);
        if let (Some(fs), Some(f)) = (caps.name("frac_sep"), caps.name("frac")) {
            out.push_str(&format!("\x1b[2m{}\x1b[0m\x1b[34m{}\x1b[0m", fs.as_str(), f.as_str()));
        }
        return out;
    }
    s.to_string()
}

fn try_process(line: &str, pos: usize) -> Option<(String, usize)> {
    static RE: Lazy<Regex> = Lazy::new(|| Regex::new(r"^[A-Za-z0-9_-]+\[\d+\]").unwrap());
    let remaining = &line[pos..];
    if let Some(m) = RE.find(remaining) {
        if m.start()!=0 { return None; }
        let s = m.as_str();
        // need to split name and pid
        let bracket = s.find('[').unwrap();
        let name = &s[..bracket];
        let pid = &s[bracket+1..s.len()-1];
        let colored = format!("\x1b[33m{}\x1b[0m\x1b[31m[\x1b[0m\x1b[36m{}\x1b[0m\x1b[31m]\x1b[0m", name, pid);
        return Some((colored, s.len()));
    }
    None
}

fn try_path(line: &str, pos: usize) -> Option<(String, usize)> {
    static RE: Lazy<Regex> = Lazy::new(|| Regex::new(r"^(?:\./|\.\./|/)?(?:[\w\-.]+/)+[\w\-.]+/?|/[\w\-.]+/[\w\-.]+(?:/[\w\-.]+)*/?").unwrap());
    let remaining = &line[pos..];
    if let Some(m) = RE.find(remaining) {
        if m.start()!=0 { return None; }
        let path_str = m.as_str();
        let slash_count = path_str.matches('/').count();
        if slash_count < 2 { return None; }
        if path_str == "/" { return None; }
        // check that after path, next char is not word char that would continue? For simplicity, allow.
        let mut out = String::new();
        let chars: Vec<char> = path_str.chars().collect();
        let mut i = 0;
        while i < chars.len() {
            if chars[i] == '/' {
                out.push_str("\x1b[33m/\x1b[0m");
                i+=1;
            } else {
                let mut seg = String::new();
                while i < chars.len() && chars[i] != '/' {
                    seg.push(chars[i]);
                    i+=1;
                }
                if !seg.is_empty() {
                    out.push_str(&format!("\x1b[32m{}\x1b[0m", seg));
                }
            }
        }
        return Some((out, path_str.len()));
    }
    None
}

