#[derive(Debug, Clone)]
struct Style {
    fg: Option<String>,
    bg: Option<String>,
    bold: bool,
    faint: bool,
    italic: bool,
    underline: bool,
}

impl Style {
    fn to_ansi(&self) -> String {
        let mut codes: Vec<String> = Vec::new();
        if self.bold { codes.push("1".to_string()); }
        if self.faint { codes.push("2".to_string()); }
        if self.italic { codes.push("3".to_string()); }
        if self.underline { codes.push("4".to_string()); }
        if let Some(bg) = &self.bg {
            if let Some(c) = bg_code(bg) { codes.push(c.to_string()); }
        }
        if let Some(fg) = &self.fg {
            if let Some(c) = fg_code(fg) { codes.push(c.to_string()); }
        }
        codes.join(";")
    }
    fn has_bg(&self) -> bool { self.bg.is_some() }
}

#[derive(Debug, Clone)]
struct CustomKeyword {
    words: Vec<String>,
    style: Style,
}

fn parse_config(path: &str) -> Result<Vec<CustomKeyword>, String> {
    let content = std::fs::read_to_string(path).map_err(|_| "could not find the TOML file".to_string())?;
    let value: toml::Value = content.parse::<toml::Value>().map_err(|e| e.to_string())?;
    let mut keywords = Vec::new();
    if let Some(kw) = value.get("keywords") {
        if let Some(arr) = kw.as_array() {
            for item in arr {
                let words = item.get("words").and_then(|v| v.as_array()).ok_or("missing field `words`")?;
                let words_vec: Vec<String> = words.iter().filter_map(|v| v.as_str().map(|s| s.to_string())).collect();
                if words_vec.is_empty() { return Err("missing field `words`".to_string()); }
                let style_val = item.get("style").ok_or("missing field `style`")?;
                let style = parse_style(style_val)?;
                keywords.push(CustomKeyword { words: words_vec, style });
            }
        } else {
            return Err("invalid type: map, expected a sequence".to_string());
        }
    }
    Ok(keywords)
}

fn parse_style(val: &toml::Value) -> Result<Style, String> {
    if let Some(s) = val.as_str() {
        return Err(format!("invalid type: string \"{}\", expected struct Style", s));
    }
    let table = val.as_table().ok_or("invalid type: expected table")?;
    let fg = table.get("fg").and_then(|v| v.as_str()).map(|s| s.to_string());
    let bg = table.get("bg").and_then(|v| v.as_str()).map(|s| s.to_string());
    if let Some(fg_str) = &fg {
        if fg_code(fg_str).is_none() {
            return Err(format!("unknown variant `{}`, expected one of `default`, `black`, `red`, `green`, `yellow`, `blue`, `magenta`, `cyan`, `white`, `bright_black`, `bright_red`, `bright_green`, `bright_yellow`, `bright_blue`, `bright_magenta`, `bright_cyan`, `bright_white`", fg_str));
        }
    }
    if let Some(bg_str) = &bg {
        if bg_code(bg_str).is_none() {
            return Err(format!("unknown variant `{}`, expected one of `default`, `black`, `red`, `green`, `yellow`, `blue`, `magenta`, `cyan`, `white`, `bright_black`, `bright_red`, `bright_green`, `bright_yellow`, `bright_blue`, `bright_magenta`, `bright_cyan`, `bright_white`", bg_str));
        }
    }
    let bold = table.get("bold").and_then(|v| v.as_bool()).unwrap_or(false);
    let faint = table.get("faint").and_then(|v| v.as_bool()).unwrap_or(false);
    let italic = table.get("italic").and_then(|v| v.as_bool()).unwrap_or(false);
    let underline = table.get("underline").and_then(|v| v.as_bool()).unwrap_or(false);
    for (k, v) in table.iter() {
        if ["bold","faint","italic","underline"].contains(&k.as_str()) {
            if !v.is_bool() {
                if let Some(s) = v.as_str() {
                    return Err(format!("invalid type: string \"{}\", expected a boolean", s));
                } else {
                    return Err(format!("invalid type: expected boolean"));
                }
            }
        }
        if ["fg","bg"].contains(&k.as_str()) {
            if !v.is_str() {
                return Err(format!("wanted string or table"));
            }
        }
    }
    Ok(Style { fg, bg, bold, faint, italic, underline })
}

fn style_from_cli_color(col: &str) -> Style {
    Style { fg: Some(col.to_string()), bg: None, bold: false, faint: false, italic: false, underline: false }
}

fn apply_style(text: &str, style: &Style) -> String {
    let code = style.to_ansi();
    if code.is_empty() {
        return text.to_string();
    }
    if style.has_bg() {
        format!("\x1b[{}m {} \x1b[0m", code, text)
    } else {
        format!("\x1b[{}m{}\x1b[0m", code, text)
    }
}

fn is_word_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

fn try_custom(line: &str, pos: usize, custom_keywords: &[CustomKeyword], cli_highlights: &[(String, Vec<String>)]) -> Option<(String, usize)> {
    let remaining = &line[pos..];
    for kw in custom_keywords {
        for word in &kw.words {
            if remaining.starts_with(word) {
                let end = pos + word.len();
                let prev_ok = if pos==0 { true } else { !is_word_char(line[..pos].chars().last().unwrap()) };
                let next_ok = if end>=line.len() { true } else { !is_word_char(line[end..].chars().next().unwrap()) };
                if prev_ok && next_ok {
                    return Some((apply_style(word, &kw.style), word.len()));
                }
            }
        }
    }
    for (color, words) in cli_highlights {
        let style = style_from_cli_color(color);
        for word in words {
            if word.is_empty() { continue; }
            if remaining.starts_with(word) {
                let end = pos + word.len();
                let prev_ok = if pos==0 { true } else { !is_word_char(line[..pos].chars().last().unwrap()) };
                let next_ok = if end>=line.len() { true } else { !is_word_char(line[end..].chars().next().unwrap()) };
                if prev_ok && next_ok {
                    return Some((apply_style(word, &style), word.len()));
                }
            }
        }
    }
    None
}

