fn try_ip(line: &str, pos: usize) -> Option<(String, usize)> {
    static RE: Lazy<Regex> = Lazy::new(|| Regex::new(r"^(?:(?:25[0-5]|2[0-4]\d|[01]?\d?\d)\.){3}(?:25[0-5]|2[0-4]\d|[01]?\d?\d)").unwrap());
    let remaining = &line[pos..];
    if let Some(m) = RE.find(remaining) {
        if m.start()!=0 { return None; }
        let ip = m.as_str();
        let end = pos + ip.len();
        if pos>0 && is_word_char(line[..pos].chars().last().unwrap()) { return None; }
        if end < line.len() && is_word_char(line[end..].chars().next().unwrap()) { return None; }
        let parts: Vec<&str> = ip.split('.').collect();
        let mut out = String::new();
        for (i, part) in parts.iter().enumerate() {
            out.push_str(&format!("\x1b[3;34m{}\x1b[0m", part));
            if i < 3 {
                out.push_str("\x1b[31m.\x1b[0m");
            }
        }
        return Some((out, ip.len()));
    }
    None
}

fn try_uuid(line: &str, pos: usize) -> Option<(String, usize)> {
    static RE: Lazy<Regex> = Lazy::new(|| Regex::new(r"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}").unwrap());
    let remaining = &line[pos..];
    if let Some(m) = RE.find(remaining) {
        if m.start()!=0 { return None; }
        let uuid = m.as_str();
        let end = pos + uuid.len();
        if pos>0 && is_word_char(line[..pos].chars().last().unwrap()) { return None; }
        if end < line.len() && is_word_char(line[end..].chars().next().unwrap()) { return None; }
        let mut out = String::new();
        for ch in uuid.chars() {
            if ch == '-' {
                out.push_str("\x1b[31m-\x1b[0m");
            } else if ch.is_ascii_digit() {
                out.push_str(&format!("\x1b[3;34m{}\x1b[0m", ch));
            } else {
                out.push_str(&format!("\x1b[3;35m{}\x1b[0m", ch));
            }
        }
        return Some((out, uuid.len()));
    }
    None
}

fn try_pointer(line: &str, pos: usize) -> Option<(String, usize)> {
