new = """fn try_ip(line: &str, pos: usize) -> Option<(String, usize)> {
    // IPv4
    static RE_V4: Lazy<Regex> = Lazy::new(|| Regex::new(r"^(?:(?:25[0-5]|2[0-4]\\d|[01]?\\d?\\d)\\.){3}(?:25[0-5]|2[0-4]\\d|[01]?\\d?\\d)").unwrap());
    let remaining = &line[pos..];
    if let Some(m) = RE_V4.find(remaining) {
        if m.start()==0 {
            let ip = m.as_str();
            let end = pos + ip.len();
            let prev_ok = if pos==0 { true } else { !is_word_char(line[..pos].chars().last().unwrap()) };
            let next_ok = if end>=line.len() { true } else { 
                let nc = line[end..].chars().next().unwrap();
                !is_word_char(nc) && nc!='.' 
            };
            // Actually for IP, we want to ensure not followed by digit or dot that is part of longer IP-like? For "192.168.0.1.5", the IP is "192.168.0.1" and ".5" is separate? In that case next char '.' but after dot digit, we should still allow IP? Let's just check not word char.
            if prev_ok && next_ok {
                let parts: Vec<&str> = ip.split('.').collect();
                let mut out = String::new();
                for (i, part) in parts.iter().enumerate() {
                    out.push_str(&format!("\\x1b[3;34m{}\\x1b[0m", part));
                    if i < 3 {
                        out.push_str("\\x1b[31m.\\x1b[0m");
                    }
                }
                return Some((out, ip.len()));
            }
        }
    }
    // IPv6
    static RE_V6: Lazy<Regex> = Lazy::new(|| Regex::new(r"^[0-9a-fA-F:]+").unwrap());
    if let Some(m) = RE_V6.find(remaining) {
        if m.start()!=0 { return None; }
        let candidate = m.as_str();
        // Must contain at least 2 colons
        if candidate.matches(':').count() < 2 {
            return None;
        }
        // Must not be just "::"
        if candidate == "::" {
            return None;
        }
        // Must contain at least one hex digit
        if !candidate.chars().any(|c| c.is_ascii_hexdigit()) {
            return None;
        }
        // Check that candidate is not followed by hex or colon (to avoid partial)
        let end = pos + candidate.len();
        if end < line.len() {
            let next = line[end..].chars().next().unwrap();
            if next.is_ascii_hexdigit() || next==':' {
                return None;
            }
            if is_word_char(next) {
                return None;
            }
        }
        if pos>0 && is_word_char(line[..pos].chars().last().unwrap()) {
            return None;
        }
        // Validate that candidate contains only hex and colon
        if !candidate.chars().all(|c| c.is_ascii_hexdigit() || c==':') {
            return None;
        }
        // Colorize: digit blue italic, letter magenta italic, colon red
        let mut out = String::new();
        for ch in candidate.chars() {
            if ch==':' {
                out.push_str("\\x1b[31m:\\x1b[0m");
            } else if ch.is_ascii_digit() {
                out.push_str(&format!("\\x1b[3;34m{}\\x1b[0m", ch));
            } else {
                out.push_str(&format!("\\x1b[3;35m{}\\x1b[0m", ch));
            }
        }
        return Some((out, candidate.len()));
    }
    None
}"""

src = src.replace(old, new)
p.write_text(src)
